package com.example.lab21; import android.content.*; import android.database.Cursor; import android.database.sqlite.*;
public class DatabaseHelper extends SQLiteOpenHelper { private static final String TABLE="Student"; public DatabaseHelper(Context c){super(c,"StudentDB",null,1);} public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE Student (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, course TEXT)");} public void onUpgrade(SQLiteDatabase db,int oldV,int newV){db.execSQL("DROP TABLE IF EXISTS Student");onCreate(db);} public boolean insertStudent(String name,String course){ContentValues v=new ContentValues();v.put("name",name);v.put("course",course);return getWritableDatabase().insert(TABLE,null,v)!=-1;} public Cursor getAllStudents(){return getReadableDatabase().rawQuery("SELECT * FROM Student",null);} public boolean updateStudent(String id,String name,String course){ContentValues v=new ContentValues();v.put("name",name);v.put("course",course);return getWritableDatabase().update(TABLE,v,"id=?",new String[]{id})>0;} public boolean deleteStudent(String id){return getWritableDatabase().delete(TABLE,"id=?",new String[]{id})>0;} }
